var step: int := 0

contains root: example::levelcrossing::TwoTrainsCanBeInTheCrossing

init {
    assume(step == 0)
    inline root.init()
    assume(root.trackA.state == example::levelcrossing::TrackState::Free)
    assume(root.trackB.state == example::levelcrossing::TrackState::Free)
    step := 1
}

tran {
    assume(step == 1)
    inline root.main()
    assume(root.trackA.state == example::levelcrossing::TrackState::Approaching)
    assume(root.trackB.state == example::levelcrossing::TrackState::Approaching)
    step := 2
} or {
    assume(step == 2)
    inline root.main()
    assume(root.trackA.state == example::levelcrossing::TrackState::Near)
    assume(root.trackB.state == example::levelcrossing::TrackState::Near)
    step := 3
} or {
    assume(step == 3)
    inline root.main()
    assume(root.trackA.state == example::levelcrossing::TrackState::InCrossing)
    assume(root.trackB.state == example::levelcrossing::TrackState::InCrossing)
    step := 4
}

prop {
    root.prop()
}
